template:
ReturnType solve(args) {
    if (base_case_condition) {
        return base_case_value;
    }
    // Do some work before recursion (optional)
    ReturnType subResult = solve(smaller_args);
    // Do some work after recursion
    return result;
}

void generate(int index, vector<int>& current, vector<int>& arr) {
    if (index == arr.size()) {
        // Process current subsequence
        return;
    }
    // Pick the current element
    current.push_back(arr[index]);
    generate(index + 1, current, arr);
    current.pop_back(); // Backtrack

    // Don't pick the current element
    generate(index + 1, current, arr);
}

void combine(int startIndex, vector<int>& current, ...) {
    if (goal_reached) {
        // Save combination
        return;
    }
    for (int i = startIndex; i < choices.size(); i++) {
        // Skip duplicates if necessary: if (i > startIndex && choices[i] == choices[i-1]) continue;
        current.push_back(choices[i]);
        combine(i + 1, current, ...); // Or combine(i, ...) if reuse is allowed
        current.pop_back();
    }
}

void permute(int index, vector<int>& nums) {
    if (index == nums.size()) {
        // Save permutation
        return;
    }
    for (int i = index; i < nums.size(); i++) {
        swap(nums[index], nums[i]);
        permute(index + 1, nums);
        swap(nums[index], nums[i]); // Backtrack
    }
}

bool backtrack(...) {
    if (is_success) return true;

    for (Choice c : choices) {
        if (isValid(c)) {
            applyChoice(c);
            if (backtrack(...)) return true;
            undoChoice(c);
        }
    }
    return false;
}

int solve(int start, int end, ...) {
    if (start >= end) return base_case;

    int best = INF;
    for (int k = start; k < end; k++) {
        int cost = solve(start, k) + solve(k + 1, end) + current_cost;
        best = min(best, cost);
    }
    return best;
}
